/**
 * TradingViewChart.jsx
 *
 * Replaces the lightweight-charts placeholder with the official
 * TradingView Advanced Chart Widget (script-embed approach).
 *
 * Props (same interface the Dashboard already passes):
 *   symbol    – plain NSE ticker, e.g. "TCS", "RELIANCE", "INFY"
 *   timeframe – one of "5m" | "15m" | "1D" | "1W"
 *
 * The component:
 *   • Maps symbol  → NSE:SYMBOL  (falls back gracefully for BSE)
 *   • Maps timeframe → TradingView interval string
 *   • Destroys and re-creates the widget whenever symbol/timeframe changes
 *   • Is fully responsive (autosize: true)
 */

import React, { useEffect, useRef } from "react";

/* ─── Timeframe → TradingView interval ─────────────────────────────────── */
const INTERVAL_MAP = {
  "1m": "1",
  "5m": "5",
  "15m": "15",
  "30m": "30",
  "1H": "60",
  "1D": "D",
  "1W": "W",
  "1M": "M",
};

function toTVInterval(timeframe) {
  return INTERVAL_MAP[timeframe] ?? "D";
}

/* ─── Symbol → TradingView exchange:ticker ──────────────────────────────── */
function toTVSymbol(symbol) {
  if (!symbol) return "NSE:NIFTY50";
  const upper = symbol.toUpperCase();
  // Already fully-qualified (e.g. "NSE:TCS" or "BSE:TCS")
  if (upper.includes(":")) return upper;
  // Default to NSE; you can extend this map for BSE-specific tickers
  return `NSE:${upper}`;
}

/* ─── TradingViewChart Component ────────────────────────────────────────── */
export default function TradingViewChart({ symbol, timeframe }) {
  const containerRef = useRef(null);
  const widgetRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    /* 1. Clean up any previous widget ------------------------------------ */
    container.innerHTML = "";
    if (widgetRef.current) {
      widgetRef.current = null;
    }

    /* 2. Create the inner div that TradingView mounts into --------------- */
    const widgetDiv = document.createElement("div");
    widgetDiv.style.width = "100%";
    widgetDiv.style.height = "100%";
    container.appendChild(widgetDiv);

    /* 3. Build widget configuration -------------------------------------- */
    const tvSymbol = toTVSymbol(symbol);
    const tvInterval = toTVInterval(timeframe);

    const widgetConfig = {
      autosize: true,
      symbol: tvSymbol,
      interval: tvInterval,
      timezone: "Asia/Kolkata",
      theme: "dark",
      style: "1",                // 1 = Candlestick
      locale: "en",
      toolbar_bg: "#131722",
      enable_publishing: false,
      allow_symbol_change: true,
      save_image: false,
      hide_side_toolbar: false,
      withdateranges: true,
      hide_volume: false,
      support_host: "https://www.tradingview.com",
      container_id: widgetDiv,   // pass the DOM element directly
    };

    /* 4. Load the TradingView script and initialise the widget ----------- */
    function initWidget() {
      if (!window.TradingView) return;
      widgetRef.current = new window.TradingView.widget(widgetConfig);
    }

    // Remove any stale TV scripts so we always load fresh
    const existingScript = document.getElementById("tradingview-widget-script");
    if (existingScript) existingScript.remove();

    const script = document.createElement("script");
    script.id = "tradingview-widget-script";
    script.src = "https://s3.tradingview.com/tv.js";
    script.async = true;
    script.onload = initWidget;
    document.head.appendChild(script);

    // If TV.js was somehow already loaded on the page
    if (window.TradingView && window.TradingView.widget) {
      initWidget();
    }

    /* 5. Cleanup ---------------------------------------------------------- */
    return () => {
      if (container) container.innerHTML = "";
      widgetRef.current = null;
    };
  }, [symbol, timeframe]); // re-run whenever symbol or timeframe changes

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%",
        height: "100%",
        minHeight: 400,
        background: "#131722",
        borderRadius: 8,
        overflow: "hidden",
      }}
    />
  );
}
